package com.nook.widgets;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.media.session.*;
import android.net.Uri;
import android.os.SystemClock;
import android.view.View;
import android.widget.RemoteViews;
import org.json.JSONObject;

/** Responsive music widgets with artwork, native elapsed time and session-bound controls. */
public final class MusicWidgets {
    private MusicWidgets(){}
    public static Class<?> provider(JSONObject config){return config.optInt("variant",0)==1?Widgets.MusicCompact.class:Widgets.Music.class;}
    public static String[] variants(){return new String[]{"Album Card","Compact player","Cover Art","Vinyl"};}
    public static JSONObject settings(Context c,int id){AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(info==null)return Widgets.defaults("music");JSONObject root=Store.config(c,id);return Widgets.kindOf(info.provider).equals("universal")?UniversalWidget.pageSettings(root,"music"):root;}
    public static PendingIntent details(Context c,int id,boolean source){return PendingIntent.getActivity(c,0,new Intent(c,NowPlayingActivity.class).putExtra("widget",id).putExtra("source",source).setData(Uri.parse("nook://now-playing/"+id+"/"+source)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    private static PendingIntent transport(Context c,int id,MusicState state,String operation){String identity=state.player.getPackageName()+"/"+state.player.getSessionToken().hashCode();return PendingIntent.getBroadcast(c,0,new Intent(c,WidgetActionReceiver.class).setAction("music_action").putExtra("widget",id).putExtra("operation",operation).putExtra("session",state.player.getSessionToken()).setData(Uri.parse("nook://music/"+id+"/"+operation+"/"+identity)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    public static void updateAll(Context c){AppWidgetManager manager=AppWidgetManager.getInstance(c);for(Class<?> provider:Widgets.providers("music"))for(int id:manager.getAppWidgetIds(new ComponentName(c,provider)))Widgets.update(c,id,"music");for(int id:manager.getAppWidgetIds(new ComponentName(c,Widgets.Universal.class)))if(UniversalWidget.currentPage(Store.config(c,id)).equals("music"))Widgets.update(c,id,"universal");}
    public static void receive(Context c,Intent intent){int id=intent.getIntExtra("widget",-1);AppWidgetProviderInfo provider=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(provider==null)return;String kind=Widgets.kindOf(provider.provider);if(!kind.equals("music")&&!(kind.equals("universal")&&UniversalWidget.currentPage(Store.config(c,id)).equals("music")))return;JSONObject config=settings(c,id);MediaSession.Token token=intent.getParcelableExtra("session");MediaController player=token==null?MediaAccess.controller(c,config):MediaAccess.find(c,token);if(player!=null&&(config.optString("musicPackage","").isEmpty()||config.optString("musicPackage").equals(player.getPackageName())))MediaAccess.transport(player,"media".equals(intent.getAction())?intent.getStringExtra("value"):intent.getStringExtra("operation"),0);updateAll(c);}
    private static Bitmap surface(int color,int radius,int width,int height){Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);b.setDensity(Bitmap.DENSITY_NONE);Paint p=new Paint(3);p.setColor(color);new Canvas(b).drawRoundRect(0,0,width,height,radius,radius,p);return b;}
    public static RemoteViews render(Context c,int id,JSONObject config,boolean small,boolean preview){
        MusicState state=new MusicState(c,config);int[] size=WidgetDesign.size(c,id,"music",config,small);int variant=WidgetDesign.clamp(config.optInt("variant",0),0,3);boolean compact=size[0]<240||small||config.optInt("density",0)==1||size[1]<210||variant==1,bar=variant==1&&size[0]>=280,cover=variant==2&&size[1]>=165&&size[0]>=240&&!small&&config.optInt("density",0)==0,embedded=config.optBoolean("_embedded",false);String layout=bar?"widget_music_bar":size[0]<240?"widget_music_narrow":cover?"widget_music_cover":compact?"widget_music_compact":"widget_music_card";RemoteViews view=new RemoteViews(c.getPackageName(),WidgetDesign.layout(c,layout,config));WidgetDesign.Colors colors=WidgetDesign.colors(config,"music");
        view.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,"music"));for(int n=0;n<3;n++)view.setImageViewResource(Widgets.BACKGROUND_IMAGES[n+1],Widgets.chipResource(config,"music"));for(int bg:Widgets.BACKGROUND_IMAGES)view.setInt(bg,"setImageAlpha",Widgets.surfaceAlpha(config));WidgetDesign.surfaces(c,view,id,"music",config,compact,new int[]{R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2});
        int dominant=MusicArt.dominant(state.art,colors.accent);if(config.optBoolean("musicTint",false)&&state.art!=null&&config.optInt("style",0)==0&&!colors.monochrome){colors.surface=MusicArt.mix(dominant,Color.luminance(colors.surface)>.4?Color.WHITE:Color.BLACK,.78f);colors.text=MusicArt.contrast(colors.surface);colors.muted=MusicArt.mix(colors.text,colors.surface,.25f);colors.accent=MusicArt.mix(dominant,colors.text,.35f);view.setImageViewBitmap(R.id.widget_surface,surface(colors.surface,WidgetDesign.radius(config),320,Math.max(80,320*size[1]/Math.max(1,size[0]))));}
        if(cover){colors.text=Color.WHITE;colors.muted=0xffd8dce5;for(int bg:new int[]{R.id.widget_action_bg0,R.id.widget_action_bg2})view.setImageViewBitmap(bg,surface(0xcc080b10,24,48,48));}
        int padding=compact?12:WidgetDesign.padding(config,false);view.setViewPadding(R.id.widget_root,Ui.dp(c,padding),Ui.dp(c,compact?8:12),Ui.dp(c,padding),Ui.dp(c,compact?8:12));
        view.setViewVisibility(R.id.widget_header,bar||embedded||bar||size[1]<145?View.GONE:View.VISIBLE);view.setViewVisibility(R.id.widget_icon,config.optBoolean("showIcon",true)?View.VISIBLE:View.GONE);view.setImageViewResource(R.id.widget_icon,R.drawable.ic_music_note);view.setInt(R.id.widget_icon,"setColorFilter",colors.accent);view.setTextViewText(R.id.widget_label,config.optString("title","").trim().isEmpty()?"NOW PLAYING":config.optString("title"));view.setViewVisibility(R.id.widget_label,config.optBoolean("showLabel",true)?View.VISIBLE:View.INVISIBLE);
        boolean allowed=MediaAccess.allowed(c),hideText=config.optBoolean("musicHideText",false);String title=state.connected?state.title:!allowed?"Connect your music":config.optString("musicPackage","").isEmpty()?"Ready when you are":"Open "+MediaAccess.appName(c,config.optString("musicPackage"));String body=state.connected?state.artist:!allowed?"Enable media access to see your player.":"Start playback in a music or podcast app.";
        view.setTextViewText(R.id.widget_title,title);view.setTextViewText(R.id.widget_body,body);String meta=state.connected?(config.optBoolean("musicShowAlbum",true)&&!state.album.trim().isEmpty()?state.album+" · ":"")+state.status+(config.optBoolean("musicShowApp",true)?" · "+state.app:""):"Your player stays in charge of playback";view.setTextViewText(R.id.widget_meta,meta);
        view.setViewVisibility(R.id.music_copy,hideText?View.GONE:View.VISIBLE);view.setViewPadding(R.id.music_copy,0,0,Ui.dp(c,!bar&&size[1]<145?32:0),0);view.setViewVisibility(R.id.music_expand,size[1]<145?View.GONE:View.VISIBLE);if(hideText)view.setViewVisibility(R.id.widget_header,View.GONE);view.setViewVisibility(R.id.widget_body,body.trim().isEmpty()?View.GONE:View.VISIBLE);view.setViewVisibility(R.id.widget_meta,bar||size[1]<165||compact&&state.connected?View.GONE:View.VISIBLE);
        for(int text:new int[]{R.id.widget_title,R.id.widget_label})view.setTextColor(text,colors.text);for(int text:new int[]{R.id.widget_body,R.id.widget_meta,R.id.music_elapsed,R.id.music_duration})view.setTextColor(text,colors.muted);view.setTextViewTextSize(R.id.widget_title,android.util.TypedValue.COMPLEX_UNIT_SP,(bar?15:compact?17:22)*WidgetDesign.scale(config));view.setTextViewTextSize(R.id.widget_body,android.util.TypedValue.COMPLEX_UNIT_SP,(bar?11:compact?12:14)*WidgetDesign.scale(config));
        boolean art=state.connected&&config.optBoolean("musicShowArt",true);view.setViewVisibility(R.id.tool_visual,art?View.VISIBLE:View.GONE);if(art){JSONObject artConfig=config;if(cover){try{artConfig=new JSONObject(config.toString()).put("musicArtShape",2);}catch(Exception ignored){}}view.setImageViewBitmap(R.id.tool_visual,cover?MusicArt.cover(state.art,config,320,Math.max(80,320*size[1]/Math.max(1,size[0])),dominant,WidgetDesign.radius(config)*320f/Math.max(1,size[0]),false):MusicArt.artwork(state.art,artConfig,320,dominant,variant==3));}
        if(cover){view.setViewVisibility(R.id.music_scrim,View.VISIBLE);view.setImageViewBitmap(R.id.music_scrim,MusicArt.cover(null,config,320,Math.max(80,320*size[1]/Math.max(1,size[0])),dominant,WidgetDesign.radius(config)*320f/Math.max(1,size[0]),true));}boolean timeline=!bar&&state.connected&&config.optBoolean("musicProgress",true)&&size[1]>=165&&!hideText;view.setViewVisibility(R.id.music_timeline,timeline?View.VISIBLE:View.GONE);view.setImageViewBitmap(R.id.widget_progress,MusicArt.progress(state.position,state.duration,colors.accent,colors.muted));boolean clock=state.playback!=null&&state.playback.getState()==PlaybackState.STATE_PLAYING&&state.playback.getPlaybackSpeed()==1f&&state.duration>0;view.setChronometer(R.id.music_elapsed,SystemClock.elapsedRealtime()-state.position,null,clock);view.setTextViewText(R.id.music_duration,state.duration>0?MusicState.time(state.duration):"LIVE / UNKNOWN LENGTH");
        view.setViewVisibility(R.id.widget_actions,state.connected?View.VISIBLE:View.GONE);String[] operations={config.optInt("musicTransport",0)==1?"back":"previous","toggle",config.optInt("musicTransport",0)==1?"forward":"next"};String[] descriptions={operations[0].equals("back")?"Back 15 seconds":"Previous track",state.playing?"Pause playback":"Play",operations[2].equals("forward")?"Forward 30 seconds":"Next track"};int[] icons={R.drawable.ic_music_previous,state.playing?R.drawable.ic_music_pause:R.drawable.ic_music_play,R.drawable.ic_music_next};
        for(int n=0;n<3;n++){int button=new int[]{R.id.widget_action0,R.id.widget_action1,R.id.widget_action2}[n];boolean enabled=state.can(operations[n]);view.setImageViewResource(button,icons[n]);view.setInt(button,"setColorFilter",colors.text);if(n!=1&&config.optInt("musicTransport",0)==1)view.setImageViewBitmap(button,MusicArt.skip(n==0?-15:30,colors.text));view.setBoolean(button,"setEnabled",enabled);view.setInt(button,"setImageAlpha",enabled?255:65);view.setContentDescription(button,descriptions[n]+(enabled?"":" · unavailable in this player"));if(!preview)view.setOnClickPendingIntent(button,enabled?transport(c,id,state,operations[n]):null);}
        view.setImageViewBitmap(R.id.widget_action_bg1,surface(colors.accent,24,56,48));view.setInt(R.id.widget_action1,"setColorFilter",MusicArt.contrast(colors.accent));view.setImageViewResource(R.id.widget_settings,R.drawable.ic_music_options);view.setImageViewResource(R.id.music_expand,R.drawable.ic_music_expand);for(int icon:new int[]{R.id.widget_settings,R.id.music_expand})view.setInt(icon,"setColorFilter",colors.text);view.setViewVisibility(R.id.widget_settings,embedded?View.GONE:View.VISIBLE);
        view.setContentDescription(R.id.widget_root,state.connected?state.title+". "+state.artist+". "+state.status+". "+MusicState.time(state.position)+" of "+(state.duration>0?MusicState.time(state.duration):"unknown duration"):title+". "+body);view.setContentDescription(R.id.widget_progress,"Track progress. Open now playing to seek.");
        if(!preview){PendingIntent open=details(c,id,false);view.setOnClickPendingIntent(R.id.widget_root,open);view.setOnClickPendingIntent(R.id.tool_visual,details(c,id,config.optInt("musicTap",0)==1));view.setOnClickPendingIntent(R.id.music_expand,open);view.setOnClickPendingIntent(R.id.widget_progress,open);view.setOnClickPendingIntent(R.id.widget_settings,LibraryWidgets.configure(c,id,"music"));}return view;
    }
}
